INSERT INTO DimDate (SK_DateID, DateValue, DateDesc, CalendarYearID, CalendarYearDesc, CalendarQtrID, CalendarQtrDesc, CalendarMonthID, CalendarMonthDesc, CalendarWeekID, CalendarWeekDesc, DayOfWeekNum, DayOfWeekDesc, FiscalYearID, FiscalYearDesc, FiscalQtrID, FiscalQtrDesc, HolidayFlag) SELECT CAST(Date.SK_DateID AS INT) AS SK_DateID, CAST(Date.DateValue AS DATE) AS DateValue, CAST(DateDesc AS TEXT) AS DateDesc, CAST(Date.CalendarYearID AS DECIMAL(4, 0)) AS CalendarYearID, CAST(Date.CalendarYearDesc AS TEXT) AS CalendarYearDesc, CAST(Date.CalendarQtrID AS DECIMAL(5, 0)) AS CalendarQtrID, CAST(Date.CalendarQtrDesc AS TEXT) AS CalendarQtrDesc, CAST(CalendarMonthID AS DECIMAL(6, 0)) AS CalendarMonthID, CAST(CalendarMonthDesc AS TEXT) AS CalendarMonthDesc, CAST(Date.CalendarWeekID AS DECIMAL(6, 0)) AS CalendarWeekID, CAST(Date.CalendarWeekDesc AS TEXT) AS CalendarWeekDesc, CAST(Date.DayOfWeekNum AS DECIMAL(1)) AS DayOfWeekNum, CAST(Date.DayOfWeekDesc AS TEXT) AS DayOfWeekDesc, CAST(Date.FiscalYearID AS DECIMAL(4, 0)) AS FiscalYearID, CAST(Date.FiscalYearDesc AS TEXT) AS FiscalYearDesc, CAST(FiscalQtrID AS DECIMAL(5, 0)) AS FiscalQtrID, CAST(Date.FiscalQtrDesc AS TEXT) AS FiscalQtrDesc, CAST(Date.HolidayFlag AS BOOLEAN) AS HolidayFlag FROM Source.Date;
